def solve(n):
    ones = ['zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine', 'ten',
            'eleven', 'twelve', 'thirteen', 'fourteen', 'fifteen', 'sixteen', 'seventeen',
            'eighteen', 'nineteen']
    tens = ['', '', 'twenty', 'thirty', 'forty', 'fifty', 'sixty', 'seventy', 'eighty', 'ninety']
    if n == 0:
        return 'zero'
    parts = []
    if n >= 1000:
        parts.append(ones[n // 1000] + ' thousand')
    rest = n % 1000
    if rest >= 100:
        parts.append(ones[rest // 100] + ' hundred')
    last = rest % 100
    if last:
        if last < 20:
            word = ones[last]
        else:
            word = tens[last // 10]
            if last % 10:
                word += '-' + ones[last % 10]
        if parts:
            word = 'and ' + word
        parts.append(word)
    return ' '.join(parts)

