def solve(n: int) -> str:
    ones = [
        "zero", "one", "two", "three", "four", "five", "six", "seven",
        "eight", "nine", "ten", "eleven", "twelve", "thirteen", "fourteen",
        "fifteen", "sixteen", "seventeen", "eighteen", "nineteen",
    ]
    tens = [
        "", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy",
        "eighty", "ninety",
    ]

    def under_thousand(value: int) -> str:
        parts = []
        hundreds, remainder = divmod(value, 100)

        if hundreds:
            parts.append(ones[hundreds] + " hundred")
            if remainder:
                parts.append("and")

        if remainder >= 20:
            ten, unit = divmod(remainder, 10)
            parts.append(tens[ten] + ("-" + ones[unit] if unit else ""))
        elif remainder:
            parts.append(ones[remainder])

        return " ".join(parts)

    if n < 1000:
        return under_thousand(n)

    thousands, remainder = divmod(n, 1000)
    result = ones[thousands] + " thousand"

    if remainder:
        connector = " and " if remainder < 100 else " "
        result += connector + under_thousand(remainder)

    return result
